"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83570"],{73968(e){e.exports=JSON.parse('{"id":"FIN-030","slug":"financial-security","term":"Financial Security","also_known_as":[],"difficulty":"Beginner","definition":"Financial security is having enough money, savings and protection to cover your needs, handle unexpected events and avoid serious financial hardship, both now and in the future.","explanation":["Financial security is about stability and peace of mind. A financially secure person can pay their regular bills, cope with a surprise expense without going into heavy debt and expect to be able to support themselves in old age.","Several things build financial security. A steady income covers day-to-day needs. An emergency fund absorbs shocks, such as a car repair or temporary job loss. Manageable debt means repayments do not crowd out other needs. Insurance protects against large losses, such as illness, disability or damage to a home. Retirement savings provide for later life.","Financial security is different from being rich. Someone with a modest income, no high-cost debt, six months of savings and suitable insurance may be more financially secure than a high earner who spends everything and carries large debts.","It is also different from financial independence. Security means you can handle life\'s ups and downs without crisis; independence means you no longer need to work at all. Security usually comes first."],"note":"","total":1500,"prev":{"slug":"financial-scam","term":"Financial Scam"},"next":{"slug":"financial-statement","term":"Financial Statement"}}')}}]);